class CmiRegistrationFlags(TextualConvention, Bits):
    description = 'This data type is used to define the registration\n        flags for Mobile IP registration extension:\n           reverseTunnel\n               -- Request to support reverse tunneling.\n           gre\n               -- Request to use GRE\n           minEnc\n               -- Request to use minimal encapsulation\n           decapsulationByMN\n               -- Decapsulation by mobile node\n           broadcastDatagram\n               -- Request to receive broadcasts\n           simultaneousBindings\n               -- Request to retain prior binding(s)'
    status = 'current'
    namedValues = NamedValues(("reverseTunnel", 0), ("gre", 1), ("minEnc", 2), ("decapsulationbyMN", 3), ("broadcastDatagram", 4), ("simultaneousBindings", 5))

class CmiEntityIdentifierType(TextualConvention, Integer32):
    description = 'A value that represents a type of Mobile IP entity\n        identifier.\n        other(1)     Indicates identifier which \n                     is not in one of the formats defined \n                     below.\n\n        ipaddress(2) IP address as defined by InetAddressIPv4\n                     textual convention in INET-ADDRESS-MIB.\n\n        nai(3)       A network access identifier as defined by\n                     the CmiEntityIdentifier textual \n                     convention.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3))
    namedValues = NamedValues(("other", 1), ("ipaddress", 2), ("nai", 3))

class CmiEntityIdentifier(TextualConvention, OctetString):
    description = 'Represents the generic identifier for Mobile IP\n        entities. A CmiEntityIdentifier value is always \n        interpreted within the context of a\n        CmiEntityIdentifierType  value. \n                     Foreign agents and Home agents are \n        identified by the IP addresses. Mobile nodes can be \n        identified in more than one way e.g. IP addresses, \n        network access identifiers (NAI). If mobile node is \n        identified by  something other than IP address say by \n        NAI and it gets IP address dynamically from the home \n        agent then value of object of this type should be same\n        as NAI. This is because then IP address is not tied \n        with mobile node and it can change across registrations \n        over period of time.'
    status = 'current'
    subtypeSpec = OctetString.subtypeSpec + ValueSizeConstraint(1, 255)

class CmiSpi(TextualConvention, Unsigned32):
    reference = 'RFC-2002 - IP Mobility Support, section 3.5.1'
    description = 'An index identifying a security context between a pair\n        of nodes among the contexts available in the Mobility\n        Security Association.  SPI values 0 through 255 are\n        reserved and MUST NOT be used in any Mobility Security\n        Association.'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(256, 4294967295)

class CmiMultiPathMetricType(TextualConvention, Integer32):
    description = 'An enumerated value that represents a metric type\n        that is used for calculating the metric for routes \n        when multiple routes are created.\n        hopcount(1)  Hop count\n                     Routes would be inserted with metric\n                     as 1 - hop count.\n        bandwidth(2) bandwidth\n                     Routes would be inserted with metric\n                     using the roaming interface bandwidth.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2))
    namedValues = NamedValues(("hopcount", 1), ("bandwidth", 2))

class CmiTunnelType(TextualConvention, Integer32):
    description = "This textual convention lists the tunneling protocols in use\n        between a HA and CoA.\n\n        The semantics are as follows.\n\n                'ipinip' - This indicates that IP-in-IP protocol is in\n                           use for tunnel encapsulation.\n\n                'gre'    - This indicates that GRE protocol is in use\n                           for tunnel encapsulation."
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2))
    namedValues = NamedValues(("ipinip", 1), ("gre", 2))

